    @SerialName("idle") IDLE("idle"),
    @SerialName("waiting") WAITING("waiting"),
    @SerialName("compare") COMPARE("compare"),
    @SerialName("failed") FAILED("failed"),
    ;

    companion object {
        fun of(value: String): E2eeApprovalState? = entries.firstOrNull { it.value == value }
    }
}

