    @SerialName("approve") APPROVE("approve"),
    @SerialName("passphrase") PASSPHRASE("passphrase"),
    @SerialName("recovery") RECOVERY("recovery"),
    ;

    companion object {
        fun of(value: String): E2eeUnlockMethod? = entries.firstOrNull { it.value == value }
    }
}

