)

@Serializable
data class TextLayoutArgs(
    /** Up to 64 texts, each up to 4,000 characters, set one after another in the same style. */
    val texts: List<String>,
    /** The app's sans (Instrument Sans) or display face (Spectral). */
    val family: TextLayoutArgs.Family,
    /** CSS pixels (the `px` names are Doubles in the native contract). */
    val pxSize: Double,
    val pxLineHeight: Double,
    /** Default 400. */
    val weight: Long? = null,
    /** CSS pixels (default 0). */
    val pxLetterSpacing: Double? = null,
    /** The paragraph's width in CSS pixels. */
    val pxWidth: Double,
    val wrap: TextLayoutArgs.Wrap,
    /** `white-space: pre-line` (line breaks in the text kept), else normal. */
    val pre: Boolean? = null,
    /**
     * A `-webkit-line-clamp` box of this many lines, as a card's preview is (one line more comes back, so a caller
     * knows there's more).
     */
    val clamp: Long? = null,
) {
    @Serializable
    enum class Family(val value: String) {
        @SerialName("sans") SANS("sans"),
        @SerialName("display") DISPLAY("display"),
        ;

        companion object {
            fun of(value: String): Family? = entries.firstOrNull { it.value == value }
        }
    }

    @Serializable
    enum class Wrap(val value: String) {
        @SerialName("pretty") PRETTY("pretty"),
        @SerialName("wrap") WRAP("wrap"),
        @SerialName("balance") BALANCE("balance"),
        ;

        companion object {
            fun of(value: String): Wrap? = entries.firstOrNull { it.value == value }
        }
    }
}

@Serializable
data class TextLayoutResult(
    /** Each text's lines, as laid out, trailing spaces dropped; an empty line for each blank one. */
    val lines: List<List<String>>,
)
